import { useCallback, useMemo, useState } from 'react';
import { JxButton, JxCalendar } from '@jinx-ui/react';

type ReportDatePickerProps = {
  value?: Date | null;
  defaultValue?: Date | null;
  onChange?: (value: Date | null) => void;
  locale?: string;
};

const DAY_MS = 24 * 60 * 60 * 1000;

const startOfDay = (date: Date) =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const isSameDay = (a: Date | null, b: Date | null) =>
  a != null && b != null && startOfDay(a).getTime() === startOfDay(b).getTime();

export default function ReportDatePicker({
  value,
  defaultValue = null,
  onChange,
  locale = 'ru-RU',
}: ReportDatePickerProps) {
  const [internalDate, setInternalDate] = useState<Date | null>(defaultValue);
  const isControlled = value !== undefined;
  const date = isControlled ? value : internalDate;

  const commit = useCallback(
    (next: Date | null) => {
      if (!isControlled) setInternalDate(next);
      onChange?.(next);
    },
    [isControlled, onChange],
  );

  const presets = useMemo(() => {
    const today = startOfDay(new Date());
    return [
      { id: 'today', label: 'Сегодня', date: today },
      { id: 'yesterday', label: 'Вчера', date: new Date(today.getTime() - DAY_MS) },
      { id: 'week', label: 'Неделя назад', date: new Date(today.getTime() - 7 * DAY_MS) },
    ];
  }, []);

  const formatted = useMemo(
    () =>
      date
        ? new Intl.DateTimeFormat(locale, { dateStyle: 'long' }).format(date)
        : null,
    [date, locale],
  );

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '12px',
        padding: '16px',
        maxWidth: '340px',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        background: 'var(--jx-surface)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
        boxShadow: 'var(--jx-shadow-sm)',
      }}
    >
      <div
        role="group"
        aria-label="Быстрый выбор даты отчёта"
        style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}
      >
        {presets.map((preset) => {
          const active = isSameDay(date, preset.date);
          return (
            <JxButton
              key={preset.id}
              size="sm"
              variant={active ? 'secondary' : 'outline'}
              aria-pressed={active}
              onClick={() => commit(preset.date)}
            >
              {preset.label}
            </JxButton>
          );
        })}
      </div>

      <JxCalendar locale={locale} value={date} onValueChange={commit} />

      <p
        aria-live="polite"
        style={{
          margin: 0,
          fontSize: '0.875rem',
          color: 'var(--jx-text-2)',
        }}
      >
        {formatted
          ? `Дата отчёта: ${formatted}`
          : 'Дата не выбрана — выберите день в календаре или быстрый вариант выше.'}
      </p>
    </div>
  );
}

